import 'bootstrap/dist/css/bootstrap.min.css';
import { Component } from 'react';

class App extends Component {
  constructor(props) {
    super(props);
    this.state = {
      deseos: ["Gambas", "Jamón"]
    };
  }

  handleAniadirDeseo(event) {
    event.preventDefault();

    let aux = this.state.deseos.slice();
    aux.push(event.target.deseo.value);

    this.setState({ deseos: aux });
    event.target.deseo.value = "";
  }

  render() {
    return (
      <div className="App">
        <h1>LISTA DE DESEOS</h1>

        <div>
          <p><strong>Añade tu regalo favorito</strong></p>
        </div>

        <DesireList deseos={this.state.deseos} />

        <Desire onAddDeseo={this.handleAniadirDeseo.bind(this)} />
      </div>
    );
  }
}

const PrintDeseo = (props) => {
  return (
    <li>{props.deseo}</li>
  );
};

class DesireList extends Component {
  render() {
    return (
      <ul>
        {
          this.props.deseos.map(
            (d, index) => <PrintDeseo key={index} deseo={d} />
          )
        }
      </ul>
    );
  }
}

class Desire extends Component {
  render() {
    return (
      <form onSubmit={this.props.onAddDeseo}>
        <input
          type="text"
          placeholder="Escribe tu deseo"
          name="deseo"
        />
        <button type="submit">Añadir</button>
      </form>
    );
  }
}

export default App;
